import requests
from concurrent.futures import ThreadPoolExecutor

BASE_URL = "https://api.socbench.example"

def update_thresholds():
    return requests.put(
        f"{BASE_URL}/facilities/567/thresholds",
        json={"thresholds": {"CO2": 1000, "SO2": 500}},
    )

def get_completion_rates():
    return requests.get(f"{BASE_URL}/analytics/completion-rates")

def get_emissions():
    return requests.get(f"{BASE_URL}/facilities/567/emissions")

def update_task():
    return requests.put(
        f"{BASE_URL}/tasks/789",
        json={
            "title": "Allocate resources for emissions compliance",
            "description": "Update resource allocation to support facility emissions compliance. Technical assistance may be needed to verify the allocation.",
            "resources": ["compliance-support", "emissions-monitoring"],
        },
    )

with ThreadPoolExecutor(max_workers=3) as executor:
    thresholds_future = executor.submit(update_thresholds)
    completion_rates_future = executor.submit(get_completion_rates)
    emissions_future = executor.submit(get_emissions)

thresholds_response = thresholds_future.result()
completion_rates_response = completion_rates_future.result()
emissions_response = emissions_future.result()
task_response = update_task()

thresholds_response.raise_for_status()
completion_rates_response.raise_for_status()
emissions_response.raise_for_status()
task_response.raise_for_status()

completion_rates = completion_rates_response.json()
emissions_data = emissions_response.json()

