import requests

BASE_URL = "https://api.socbench.example"

def register_patient(patient_details):
    response = requests.post(
        f"{BASE_URL}/patients",
        json=patient_details,
        timeout=30,
    )
    response.raise_for_status()
    return response.json()["id"]

def get_upcoming_consultations(patient_id):
    response = requests.get(
        f"{BASE_URL}/patients/{patient_id}/scheduled-consultations",
        timeout=30,
    )
    response.raise_for_status()
    return response.json()

def validate_insurance_coverage(patient_id):
    response = requests.get(
        f"{BASE_URL}/patients/{patient_id}/history",
        timeout=30,
    )
    response.raise_for_status()
    return response.json()

def share_medical_data_with_provider(patient_id, provider_id):
    response = requests.get(
        f"{BASE_URL}/patients/{patient_id}/records",
        timeout=30,
    )
    response.raise_for_status()
    medical_records = response.json()

    # The documented API provides no endpoint for sharing records directly.
    # Return the records and intended provider for an authorized sharing workflow.
    return {
        "provider_id": provider_id,
        "medical_records": medical_records,
    }

def process_patient(patient_details, provider_id):
    patient_id = register_patient(patient_details)
    consultations = get_upcoming_consultations(patient_id)
    coverage_history = validate_insurance_coverage(patient_id)
    shared_data = share_medical_data_with_provider(patient_id, provider_id)

    return {
        "patient_id": patient_id,
        "consultations": consultations,
        "coverage_history": coverage_history,
        "provider_data": shared_data,
    }

patients_to_register = [
