import requests

BASE_URL = "https://api.socbench.example"
session = requests.Session()
session.headers.update({"Accept": "application/json", "Content-Type": "application/json"})

# Gather current demand and use it to adjust distribution for the specified regions.
demand_response = session.get(f"{BASE_URL}/realtime-demand")
demand_response.raise_for_status()
demand_data = demand_response.json()

regions = ["region-1", "region-2"]
zone_demands = {
    zone["zone_id"]: zone["demand"]
    for zone in demand_data.get("zones", [])
    if "zone_id" in zone and "demand" in zone
}

for region in regions:
    if region in zone_demands:
        response = session.put(
            f"{BASE_URL}/adjust-distribution",
            json={
                "zone_id": region,
                "new_distribution_strategy": {
                    "supply_limit": zone_demands[region],
                    "time_frame": "immediate",
                },
            },
        )
        response.raise_for_status()

# Review the available region configuration endpoint and update the specified region
# with billing-template configuration details.
billing_region = "region-1"
config_response = session.put(
    f"{BASE_URL}/regions/config",
    json={
        "region": billing_region,
        "new_config_params": {"billing_template_reviewed": True},
    },
)
config_response.raise_for_status()

